#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cstdint>

int64_t getCandiesEaten(int64_t n, int64_t k) {
    if (n == 1) return 0;
    n--;
    int64_t candies = 1;
    int64_t sum = 2;
    int64_t consumed = 0;
    while (n > 0) {
        while (candies <= k) {
            candies += sum;
            sum++;
            n--;
        }
        int64_t candiesToSubtract = candies - k;
        n -= candiesToSubtract;
        consumed += candiesToSubtract;
        candies -= candiesToSubtract;
    }
    return consumed;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string input((std::istreambuf_iterator<char>(std::cin)), std::istreambuf_iterator<char>());

    std::vector<std::string> lines;
    std::stringstream ss(input);
    std::string line;
    while (std::getline(ss, line)) {
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        lines.push_back(line);
    }

    if (lines.empty()) return 0;

    std::stringstream firstLine(lines[0]);
    int64_t n, k;
    firstLine >> n >> k;

    std::cout << getCandiesEaten(n, k) << '\n';

    return 0;
}

